// Standalone idempotent seed for the STAGING demo account.
// Run with the STAGING DATABASE_URL in env. Writes ONLY to nxeon_staging.
//   export $(grep '^DATABASE_URL' /opt/nxeon-staging/.env) && node seed-demo.mjs
import { PrismaClient } from '/opt/nxeon-wt-mktg/node_modules/@prisma/client/default.js';
import bcrypt from '/opt/nxeon-wt-mktg/node_modules/bcryptjs/index.js';

const db = new PrismaClient();

// --- Safety: refuse to run against anything but the staging DB ---
const url = process.env.DATABASE_URL || '';
if (!/nxeon_staging/.test(url)) {
  console.error('REFUSING TO RUN: DATABASE_URL is not nxeon_staging ->', url.replace(/:[^:@/]*@/, ':***@'));
  process.exit(1);
}

const DEMO_EMAIL = 'demo@nxeon.cloud';
const DEMO_PASSWORD = 'NxeonDemo2026!';
const now = new Date();
const future = (days) => new Date(now.getTime() + days * 86400_000);
const past = (days) => new Date(now.getTime() - days * 86400_000);

// Reuse existing catalogue IDs (verified present in staging).
const PLAN = {
  starter: 'cmrxfhsmx0001hl71j2fbcrzu',
  standard: 'cmrxfhsmy0002hl71189n5nv0',
  pro: 'cmrxfhsmz0003hl71i99aio86',
};
const OS = {
  ubuntu24: 'cmrxfhsn10005hl71500l53m3',
  ubuntu22: 'faee7c12af8352a8d7655623f74f42e1',
  debian13: 'cmrxfhsn20006hl712kbhavcz',
  minecraft: 'cmrxjkpa0000chllkjetq9mcu',
  rust: 'cmrxlnscc000mhl91rb8a2hmn',
};
const GAMEPLAN = {
  minecraft4: 'cmrytasit0003hli13obqzfv8', // Minecraft — 4 GB / 20 slots (basePlan standard)
  rust4: 'cmrytasj0000bhli1fesh4gjw',      // Rust — 4 GB / 40 slots (basePlan standard)
};
const HPLAN = {
  starter: 'cmsorshah0000hl99lf1v1aj4',
  business: 'cmsorshak0001hl99kn9sai3r',
  pro: 'cmsorsham0002hl99wb0pnz2o',
};

async function main() {
  // 1) Demo user (idempotent upsert by email)
  const passwordHash = await bcrypt.hash(DEMO_PASSWORD, 12);
  const user = await db.user.upsert({
    where: { email: DEMO_EMAIL },
    update: {
      name: 'Demo User',
      passwordHash,
      role: 'CUSTOMER',
      balanceCents: 5000,
      emailVerifiedAt: now,
      suspended: false,
    },
    create: {
      email: DEMO_EMAIL,
      name: 'Demo User',
      passwordHash,
      role: 'CUSTOMER',
      balanceCents: 5000,
      emailVerifiedAt: now,
    },
  });
  console.log('user', user.id, user.email);

  // 2) Mock VPS Node (upsert by unique name) — non-routable, obviously fake creds
  const node = await db.node.upsert({
    where: { name: 'demo-node-1' },
    update: { status: 'ONLINE', enabled: true, lastSeenAt: now },
    create: {
      name: 'demo-node-1',
      pveNode: 'demo-pve-1',
      apiUrl: 'https://203.0.113.2:8006',
      tokenId: 'demo@pve!seed',
      tokenSecret: 'demo-seed-not-a-real-secret',
      publicIp: '203.0.113.2',
      isPrimary: false,
      enabled: true,
      status: 'ONLINE',
      lastSeenAt: now,
    },
  });

  // 3) Mock Hosting Node (upsert by unique name)
  const hnode = await db.hostingNode.upsert({
    where: { name: 'demo-hosting-1' },
    update: { status: 'ONLINE', enabled: true, lastSeenAt: now },
    create: {
      name: 'demo-hosting-1',
      publicIp: '203.0.113.3',
      sshHost: '203.0.113.3',
      sshPort: 22,
      hostnameFqdn: 'web1.sites.nxeon.cloud',
      maxAccounts: 200,
      diskTotalGB: 500,
      enabled: true,
      status: 'ONLINE',
      lastSeenAt: now,
    },
  });

  // --- Idempotency: wipe this demo user's previously-seeded resources ---
  await db.server.deleteMany({ where: { userId: user.id } });
  // HostingAccount children (subdomains/addons) cascade on delete.
  await db.hostingAccount.deleteMany({ where: { userId: user.id } });

  // 4) VPS servers
  const vps = [
    { name: 'web-01', label: 'Production Web', hostname: 'web-01.nxeon.cloud',
      planId: PLAN.standard, osTemplateId: OS.ubuntu24, ipAddress: '203.0.113.11', sshPort: 22201, vmid: 990101 },
    { name: 'db-01', label: 'Postgres DB', hostname: 'db-01.nxeon.cloud',
      planId: PLAN.pro, osTemplateId: OS.debian13, ipAddress: '203.0.113.12', sshPort: 22202, vmid: 990102 },
    { name: 'app-01', label: 'Staging App', hostname: 'app-01.nxeon.cloud',
      planId: PLAN.starter, osTemplateId: OS.ubuntu22, ipAddress: '203.0.113.13', sshPort: 22203, vmid: 990103 },
  ];
  for (const s of vps) {
    const row = await db.server.create({ data: {
      ...s, userId: user.id, nodeId: node.id,
      status: 'RUNNING', autoRenew: true, termMonths: 1, termPromoPercent: 0,
      ipv6: '2001:db8::' + s.vmid,
      createdAt: past(45), expiresAt: future(285),
    }});
    console.log('vps', row.name, row.ipAddress, row.status);
  }

  // 5) Game servers (gamePlanId + matching osTemplate; planId = the gameplan's base plan)
  const games = [
    { name: 'mc-survival', label: 'Survival SMP', hostname: 'mc-survival.nxeon.cloud',
      gamePlanId: GAMEPLAN.minecraft4, osTemplateId: OS.minecraft, planId: PLAN.standard,
      gameVariant: 'paper', ipAddress: '203.0.113.14', sshPort: 22204, vmid: 990104 },
    { name: 'rust-main', label: 'Main Rust', hostname: 'rust-main.nxeon.cloud',
      gamePlanId: GAMEPLAN.rust4, osTemplateId: OS.rust, planId: PLAN.standard,
      gameVariant: 'carbon', ipAddress: '203.0.113.15', sshPort: 22205, vmid: 990105 },
  ];
  for (const g of games) {
    const row = await db.server.create({ data: {
      ...g, userId: user.id, nodeId: node.id,
      status: 'RUNNING', autoRenew: true, termMonths: 1, termPromoPercent: 0,
      createdAt: past(30), expiresAt: future(300),
    }});
    console.log('game', row.name, row.gameVariant, row.ipAddress, row.status);
  }

  // 6) Hosting accounts
  async function makeHosting({ username, name, primaryDomain, planId, diskGB, maxSites, maxDatabases, diskUsedMB }) {
    return db.hostingAccount.create({ data: {
      userId: user.id, hostingNodeId: hnode.id, planId,
      username, name, primaryDomain,
      status: 'ACTIVE', sslActive: true,
      diskQuotaMB: diskGB * 1024, maxSites, maxDatabases,
      termMonths: 1, phpVersion: '8.3',
      diskUsedMB, inodesUsed: Math.round(diskUsedMB * 40), usageAt: now,
      serveHttpOk: true, serveHttpsOk: true, healthNote: 'Serving on 80/443', healthCheckedAt: now,
      provisionedAt: past(20), createdAt: past(20), expiresAt: future(345),
    }});
  }

  const store = await makeHosting({ username: 'demostore', name: 'My Store',
    primaryDomain: 'demostore.sites.nxeon.cloud', planId: HPLAN.starter,
    diskGB: 10, maxSites: 1, maxDatabases: 2, diskUsedMB: 640 });
  console.log('hosting', store.name, store.primaryDomain, store.status);

  const client = await makeHosting({ username: 'clienthub', name: 'Client Sites',
    primaryDomain: 'clienthub.sites.nxeon.cloud', planId: HPLAN.pro,
    diskGB: 50, maxSites: 50, maxDatabases: 100, diskUsedMB: 4820 });
  console.log('hosting', client.name, client.primaryDomain, client.status);

  const folio = await makeHosting({ username: 'myfolio', name: 'Portfolio',
    primaryDomain: 'myfolio.sites.nxeon.cloud', planId: HPLAN.business,
    diskGB: 25, maxSites: 10, maxDatabases: 25, diskUsedMB: 1180 });
  console.log('hosting', folio.name, folio.primaryDomain, folio.status);

  // Subdomains + addon domain on the "Client Sites" account
  await db.hostingSubdomain.create({ data: {
    accountId: client.id, label: 'shop', fqdn: 'shop.clienthub.sites.nxeon.cloud',
    docroot: '/home/clienthub/subdomains/shop/public_html', sslActive: true, status: 'ACTIVE', createdAt: past(15) }});
  await db.hostingSubdomain.create({ data: {
    accountId: client.id, label: 'blog', fqdn: 'blog.clienthub.sites.nxeon.cloud',
    docroot: '/home/clienthub/subdomains/blog/public_html', sslActive: true, status: 'ACTIVE', createdAt: past(12) }});
  await db.hostingAddonDomain.create({ data: {
    accountId: client.id, domain: 'acme-widgets.example',
    docroot: '/home/clienthub/domains/acme-widgets.example/public_html', sslActive: true, status: 'ACTIVE', createdAt: past(10) }});
  console.log('  + 2 subdomains + 1 addon domain on Client Sites');
}

main()
  .then(() => db.$disconnect())
  .catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

